<?php $layout='layouts.app'; ?>
<h1>Fees & Payments</h1><p class="muted">Read-only view of your school fee account.</p>
<div class="card" style="margin-top:var(--space-4)"><div class="card-body"><h3>Invoices</h3><table class="table"><thead><tr><th>Invoice</th><th>Date</th><th>Due</th><th>Status</th><th>Total</th><th>Paid</th><th>Balance</th></tr></thead><tbody><?php foreach($invoices as $row): ?><tr><td><?= e($row['invoice_no']) ?></td><td><?= e((string)$row['invoice_date']) ?></td><td><?= e((string)($row['due_date']??'')) ?></td><td><?= e(ucfirst((string)$row['status'])) ?></td><td><?= number_format((float)$row['total'],2) ?></td><td><?= number_format((float)$row['paid_amount'],2) ?></td><td><?= number_format((float)$row['balance'],2) ?></td></tr><?php endforeach; if(!$invoices): ?><tr><td colspan="7">No fee invoices found.</td></tr><?php endif; ?></tbody></table></div></div>
<div class="card" style="margin-top:var(--space-4)"><div class="card-body"><h3>Payments</h3><table class="table"><thead><tr><th>Receipt</th><th>Date</th><th>Amount</th><th>Method</th><th>Reference</th><th>Status</th></tr></thead><tbody><?php foreach($payments as $row): ?><tr><td><?= e($row['receipt_no']) ?></td><td><?= e((string)$row['payment_date']) ?></td><td><?= number_format((float)$row['amount'],2) ?></td><td><?= e((string)$row['method']) ?></td><td><?= e((string)($row['reference']??'')) ?></td><td><?= e(ucfirst((string)$row['status'])) ?></td></tr><?php endforeach; if(!$payments): ?><tr><td colspan="6">No payments found.</td></tr><?php endif; ?></tbody></table></div></div>
